    kon = "kon-deckshow"

    def borrar_entrada(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[BorrarEntradaResult]:
        """Remove an entry from the showcase

        Deletes the entry and its likes; the deck itself stays saved in kon-cardsim. Its author or a moderator (403 otherwise). 204 with no body.

        REST: `DELETE /api/deckshow/entries/{id}` · scope `kon:deckshow:borrar-entrada`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `deckshow__borrar-entrada`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            id: Entry id (deckshow_entries)
        """
        return self._call(OPERATIONS["borrar-entrada"], {"id": id}, None, request_options)

    def buscar_cartas(self, *, slug: Union[str, int], q: Optional[Union[str, int]] = None, page: Optional[Union[str, int]] = None, page_size: Optional[Union[str, int]] = None, request_options: Optional[RequestOptions] = None) -> Outcome[BuscarCartasResult]:
        """Search the cards of a game

        Cards of the game `slug` for the deck builder: `q` matches the name, any other query key filters on that card property (exact match, arrays match any element). Paged (`pageSize` up to 120, default 48). 404 if the game does not exist.

        REST: `GET /api/deckshow/games/{slug}/cards` · scope `kon:deckshow:buscar-cartas`
        idempotent (safe to retry) · MCP tool `deckshow__buscar-cartas`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            slug: Slug (of a game or of an entry)
            q: Name contains (case-insensitive)
            page: 1-based page
            page_size: Page size, max 120 (default 48)
        """
        return self._call(OPERATIONS["buscar-cartas"], {"slug": slug, "q": q, "page": page, "pageSize": page_size}, None, request_options)

